import re

_VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]
_DIGITS = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
_SHAPE = re.compile(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})")


def to_roman(n):
    """Upper-case Roman numeral for an integer from 1 to 3999, e.g. 1994 -> "MCMXCIV"."""
    if not 1 <= n <= 3999:
        raise ValueError(f"roman numerals need an integer from 1 to 3999: {n}")
    out = ""
    for value, numeral in _VALUES:
        count, n = divmod(n, value)
        out += numeral * count
    return out


def from_roman(s):
    """Integer for a canonical upper-case Roman numeral, e.g. "MCMXCIV" -> 1994.

    Only strings that to_roman produces are accepted; "IIII", "IC", "mcm" and "" raise ValueError.
    """
    if not s or _SHAPE.fullmatch(s) is None:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    total = 0
    for i, ch in enumerate(s):
        value = _DIGITS[ch]
        if i + 1 < len(s) and value < _DIGITS[s[i + 1]]:
            total -= value
        else:
            total += value
    # Final guard: the value must convert back to exactly this string.
    if to_roman(total) != s:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    return total
