"""Each README command cell must equal the command's help string in the registry, word for word."""
import pathlib
import re
import unittest

from textkit.cli import COMMANDS

ROOT = pathlib.Path(__file__).resolve().parent.parent


def readme_cells():
    """Map command name -> 'what it does' cell text from the README table."""
    readme = (ROOT / "README.md").read_text()
    rows = re.findall(r"^\| `([a-z]+)` \| (.*) \|$", readme, flags=re.M)
    return dict(rows)


class DocSyncTest(unittest.TestCase):
    def test_every_command_has_matching_readme_cell(self):
        cells = readme_cells()
        for name, c in COMMANDS.items():
            with self.subTest(command=name):
                self.assertIn(name, cells, f"no README row for `{name}`")
                self.assertEqual(cells[name], c["help"])
"""The README command table and the registry must agree."""
