import contextlib
import io
import unittest

from textkit.cli import main
from textkit.topwords import top_words


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class TopWordsTest(unittest.TestCase):
    def test_counts_case_insensitively(self):
        self.assertEqual(top_words("The the THE cat", 1), [("the", 3)])

    def test_splits_on_non_letters(self):
        self.assertEqual(top_words("don't", 5), [("don", 1), ("t", 1)])
        self.assertEqual(top_words("a1b-c, a", 1), [("a", 2)])

    def test_sorts_by_count_then_alphabetically(self):
        self.assertEqual(
            top_words("b a b c a b", 3),
            [("b", 3), ("a", 2), ("c", 1)],
        )
        self.assertEqual(top_words("zeta alpha mid", 3), [("alpha", 1), ("mid", 1), ("zeta", 1)])

    def test_k_larger_than_distinct_words_returns_all(self):
        self.assertEqual(top_words("x y", 10), [("x", 1), ("y", 1)])

    def test_empty_text_returns_empty_list(self):
        self.assertEqual(top_words("", 3), [])
        self.assertEqual(top_words("123 !!", 3), [])

    def test_k_below_one_raises(self):
        for k in [0, -1]:
            with self.subTest(k=k):
                with self.assertRaises(ValueError):
                    top_words("x", k)


class TopCommandTest(unittest.TestCase):
    def test_prints_top_k_lines(self):
        self.assertEqual(run("top", "b a b c a b", "--k", "2"), (0, "b 3\na 2\n", ""))

    def test_default_k_is_three(self):
        self.assertEqual(run("top", "d c c b b b a a a a")[1], "a 4\nb 3\nc 2\n")

    def test_k_below_one_exits_2_with_error(self):
        code, out, err = run("top", "x", "--k", "0")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

    def test_listed_in_commands(self):
        code, out, _ = run("commands")
        self.assertEqual(code, 0)
        self.assertIn("top", out.split())


if __name__ == "__main__":
    unittest.main()

